/**
 * The value of the input element.
 *
 * @type {string}
 */
get value() {
  return this.#input.value;
}

set value(newValue) {
  this.#input.value = newValue;
}

/**
 * The number value of the input element.
 *
 * @type {number}
 * @readonly
 */
get valueAsNumber() {
  return this.#input.valueAsNumber;
}
